globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","contest":"КИТ","language":"ru","letters":"АБВГД","count":30,"points":3,"solutionsFile":"solutions.pdf","year":2011,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"reviewed-6-7.pdf","readerFile":"6-7-reading.pdf","reviewedKey":true}, [{"title":"Визуальный вывод","question":"Какое количество устройств, представленных на рисунке, являются устройствами для вывода визуальной информации?","choices":["1","2","3","4","0"],"points":3,"steps":["Монитор выводит изображение на экран, принтер — на бумагу. Оба передают информацию, которую можно увидеть.","Клавиатура вводит данные, а колонки выводят звук. Подходят два устройства."],"answer":1,"figure":{"src":"assets/kit/2011/6-7-01.webp","alt":"Четыре компьютерных устройства."}},{"title":"Наименьшая единица информации","question":"Наименьшей единицей измерения информации служит…","choices":["1 м","1 байт","1 бот","1 баг","1 бит"],"points":3,"steps":["Один двоичный разряд может задавать одно из двух состояний, например 0 или 1. Такая единица называется битом.","В байте восемь бит, поэтому байт больше. Выбираем 1 бит."],"answer":4},{"title":"Перед выключением компьютера","question":"Выберите наиболее точный ответ. Перед выключением компьютера необходимо…","choices":["вставить дополнительные аккумуляторы","отключить питание компьютера","включить питание компьютера","отсоединить все устройства","закрыть все программы"],"points":3,"steps":["Открытые программы могут содержать данные, которые ещё не записаны. Сохрани работу и заверши программы.","После этого завершай работу системы. Из предложенного первым делом нужно закрыть программы."],"answer":4},{"title":"Цифры часов в зеркале","question":"Правильно идущие электронные часы отражаются в зеркале. Который сейчас час может быть?","choices":["12:10","12:01","01:21","21:10","10:21"],"points":3,"steps":["При зеркальном отражении слева направо крайние символы меняются местами. В электронной записи ноль сохранит форму, а 5 отражается в 2.","Отрази рисунок обратно или сравни зеркальные изображения пяти вариантов. Исходное время — 21:10."],"answer":3,"figure":{"src":"assets/kit/2011/6-7-04.webp","alt":"Отражённая индикация электронных часов."}},{"title":"Носители вирусов","question":"Компьютерные вирусы не распространяются через…","choices":["монитор","дискеты","веб-страницы","электронную почту","флэш-накопители"],"points":3,"steps":["Компьютерный вирус передаётся в виде данных. Съёмные накопители, почта и страницы могут доставлять на компьютер файлы.","Монитор показывает полученное от компьютера изображение, поэтому среди вариантов через него вирус не распространяется."],"answer":0},{"title":"Ребус о связи компьютеров","question":"Разгадайте ребус. Загаданное в ребусе слово является…","choices":["устройством вывода информации на бумажный носитель","устройством, применяющимся в системах связи и выполняющим функцию связи компьютеров друг с другом","устройством ввода информации с бумажного носителя","языком программирования","антивирусной программой"],"points":3,"steps":["Картинка изображает дом вверх ногами. Прочитай ДОМ с конца: МОД.","Запятые слева и справа от 7 убирают первую и последнюю буквы слова «семь». Остаётся ЕМ. Слово «модем» обозначает устройство связи."],"answer":1,"figure":{"src":"assets/kit/2011/6-7-06.webp","alt":"Дом вверх ногами, цифра 7 и две запятые."}},{"title":"Что делает архиватор","question":"Архиватором называют программу, которая…","choices":["помещает файлы в корзину","позволяет рисовать графические объекты","лечит заражённые файлы","осуществляет упаковку (сжатие) одного или более файлов","является текстовым редактором"],"points":3,"steps":["Когда нужно передать несколько файлов вместе, их можно упаковать в один архив. Многие архивы ещё и сжимают данные.","Создавать такие архивы и распаковывать их позволяет архиватор. Подходит вариант Г."],"answer":3},{"title":"Продолжение ряда устройств","question":"Продолжите ряд: геймпад, сканер, мышь, …","choices":["принтер","процессор","клавиатура","монитор","колонки"],"points":3,"steps":["Геймпад посылает команды игрока, сканер вводит изображение, мышь вводит движения и щелчки. Все три устройства отправляют данные в компьютер.","То же делает клавиатура: вводит символы и команды. Принтер, монитор и колонки выполняют вывод, процессор обрабатывает данные."],"answer":2},{"title":"Произведение с коэффициентом","question":"Известно, что a · b = 24. Чему равно (2 · a) · (b : 3)?","choices":["8","10","15","16","18"],"points":3,"steps":["Перегруппируй произведение: (2 · a) · (b : 3) = (a · b) · 2 : 3.","Подставь 24. После умножения на 2 и деления на 3 выйдет 16."],"answer":3},{"title":"Следы на снегу","question":"Вася шёл на урок информатики и оставил на снегу следы. Выберите верную последовательность Васиных действий.","choices":["Вася сначала бежал, потом шёл","Вася сначала стоял, потом шёл, потом прыгал на одной ноге","Вася сначала стоял, потом прыгал на одной ноге, потом шёл","Вася сначала прыгал на одной ноге, потом стоял, потом шёл","Вася всё время бежал"],"points":3,"steps":["Слева два отпечатка рядом поперёк пути: Вася стоит. Дальше подряд следы одной ноги, значит, он прыгает на ней.","Ближе к концу следы левой и правой ноги чередуются. Вася перешёл на шаг. Получается последовательность В."],"answer":2,"figure":{"src":"assets/kit/2011/6-7-10.webp","alt":"Отпечатки ног на снегу слева направо."}},{"title":"Шесть ячеек диапазона","question":"В электронной таблице выделена группа ячеек C1:D3. Сколько ячеек входит в эту группу?","choices":["6","7","3","4","5"],"points":4,"steps":["Диапазон начинается в C1 и заканчивается в D3. Столбцов два, C и D.","Берём по три строки в каждом столбце. Получаем 2 · 3 = 6 ячеек."],"answer":0},{"title":"Анаграммы об устройствах","question":"Анаграммы — это головоломки, в которых переставляются буквы в словах. Расшифруйте слова в анаграммах. Выберите лишнее слово.","choices":["укбноту","текормпью","дмемо","авоорк","шмьы"],"points":4,"steps":["Восстанови порядок букв: ноутбук, компьютер, модем, корова, мышь.","В этом наборе мышь относится к компьютерной технике вместе с первыми тремя словами. Корова — единственное слово, не связанное с компьютером."],"answer":3},{"title":"Числа рядом со степенью двух","question":"Найдите закономерность и определите следующий член последовательности: 3, 7, 15, 31, 63, …","choices":["121","123","125","127","129"],"points":4,"steps":["Прибавь 1 к каждому члену. Получатся 4, 8, 16, 32, 64 — числа, которые каждый раз удваиваются.","Следующее увеличенное число 128. Верни вычтенную единицу: 128 − 1 = 127."],"answer":3},{"title":"Пересадка за компьютерами","question":"В компьютерном классе всего три компьютера, за которыми сидели Маша, Петя и Вася. Известно, что Петя сидел левее Васи, а Маша — левее Пети. Затем они пересели, и Вася стал сидеть левее Пети, но правее Маши. Кто остался сидеть за своим компьютером?","choices":["Маша, Петя, Вася","Маша, Петя","Петя","Вася","Маша"],"points":4,"steps":["Первый порядок слева направо: Маша, Петя, Вася. Петя находится между двумя остальными.","После пересадки слева направо Маша, Вася, Петя. Своё левое место сохранила только Маша."],"answer":4},{"title":"Перестановка строк и столбцов","question":"В электронной таблице переставляются местами столбцы C и D, а затем строки 2 и 4. Какое значение будет содержаться в ячейке C4?","choices":["1","3","5","6","9"],"points":4,"steps":["Проследи C4 в обратном порядке. До обмена строк она находилась во второй строке, то есть в C2.","До обмена столбцов это была D2. В исходной таблице D2 равно 9."],"answer":4,"context":"Столбцы: A · B · C · D\nСтрока 1: 1 · 5 · 6 · 8\nСтрока 2: 3 · 4 · 7 · 9\nСтрока 3: 4 · 3 · 5 · 3\nСтрока 4: 5 · 7 · 6 · 8"},{"title":"Пропавшая клавиша","question":"Младший брат выдрал клавишу на Вовиной клавиатуре. Без какой клавиши остался Вова?","choices":["Shift","Ctrl","Alt","Enter","Delete"],"points":4,"steps":["Сравни пропуск с соседними рядами. Он находится справа от букв, где заканчивается строка, и занимает заметно больше места, чем обычная клавиша.","В этом месте обычно стоит Enter для переноса строки и подтверждения ввода. Ctrl и Alt располагаются в нижнем ряду, а Delete — в отдельном блоке."],"answer":3,"figure":{"src":"assets/kit/2011/6-7-16.webp","alt":"Клавиатура с пропуском на месте одной клавиши."}},{"title":"Удары часов с боем","question":"Часы с боем бьют каждый час столько раз, сколько часов показывает часовая стрелка. В течение 12 часов прозвучит…","choices":["12 ударов","48 ударов","64 удара","78 ударов","144 удара"],"points":4,"steps":["За 12 часов стрелка побывает на каждом из 12 делений. Сложи числа от 1 до 12.","Соедини крайние часы в пары: 1 + 12, 2 + 11 и так далее. Каждая из шести пар даёт 13 ударов, всего 78."],"answer":3},{"title":"Назначение пяти устройств","question":"Установите соответствие.","choices":["1-e, 2-c, 3-d, 4-b, 5-a","1-d, 2-c, 3-e, 4-b, 5-a","1-b, 2-e, 3-c, 4-d, 5-a","1-e, 2-c, 3-a, 4-b, 5-d","1-c, 2-e, 3-a, 4-b, 5-d"],"points":4,"steps":["Ввести текст позволяет клавиатура (1-e), а напечатать видимое изображение — принтер (2-c).","Звук выводят колонки (3-d), записывает звук микрофон (4-b). Графическую информацию вводит плата видеозахвата (5-a). Подходит набор А."],"answer":0,"context":"1. Устройство ввода текстовой информации.\n2. Устройство для вывода визуальной информации.\n3. Устройство для вывода звуковой информации.\n4. Устройство для ввода звуковой информации.\n5. Устройство для ввода графической информации.\n\na. Плата видеозахвата.\nb. Микрофон.\nc. Принтер.\nd. Колонки.\ne. Клавиатура."},{"title":"Год первого спутника","question":"В этом году представлен первый в мире полностью электронный калькулятор и написана реализация FORTRAN — первого языка программирования высокого уровня, имеющего транслятор. Этот год был переломным для всей истории человечества: 4 октября в СССР произведён запуск первого искусственного спутника Земли. Это величайшее событие затмило собой даже такое достижение СССР, как спуск на воду атомного ледокола «Ленин» — первого в мире надводного судна с ядерной силовой установкой. Это был…","choices":["1947 год","1957 год","1967 год","1977 год","1987 год"],"points":4,"steps":["Выдели событие с точной датой. Первый искусственный спутник Земли стартовал 4 октября 1957 года.","Это соответствует варианту Б. Ледокол «Ленин» тоже спустили на воду в 1957 году."],"answer":1},{"title":"Документ с алгоритмом","question":"Какой из перечисленных документов содержит алгоритм?","choices":["меню в школьной столовой","расписание уроков в компьютерном классе","список учеников, допущенных к уроку","список действий (инструкция по включению ЭВМ), которые необходимо выполнить, чтобы приступить к работе в компьютерном классе","содержание классного журнала"],"points":4,"steps":["Алгоритм задаёт действия в таком порядке, чтобы исполнитель достиг результата. Проверь, где есть последовательность действий.","Инструкция по включению компьютера ведёт от первого действия к готовности начать работу. Меню, расписание и списки сами таких действий не задают."],"answer":3},{"title":"Три квадрата из отрезков","question":"На клетчатой бумаге проведены линии, как показано на рисунке. Фигура образована из 17 одинаковых отрезков, которые образуют 6 одинаковых квадратов. Какое наименьшее количество отрезков необходимо убрать, чтобы оставшиеся отрезки образовывали ровно три одинаковых квадрата без лишних линий?","choices":["6","7","3","4","5"],"points":5,"steps":["В сетке только два больших квадрата, так что три одинаковых должны быть маленькими. Они используют не больше 3 · 4 = 12 единичных отрезков, если стороны не перекрываются. Значит, из 17 придётся убрать хотя бы пять.","Оставь левый и правый квадраты верхнего ряда и средний нижнего. Эти квадраты имеют разные стороны и вместе используют 12 отрезков. Остальные пять можно убрать."],"answer":4,"adaptation":"Уточнено, что оставшиеся отрезки входят в три квадрата и лишних отрезков быть не должно.","figure":{"src":"assets/kit/2011/6-7-21.svg","alt":"Прямоугольная сетка из двух рядов и трёх столбцов."}},{"title":"Пароль или новая программа","question":"Программист Клава Крутая может написать программу по анализу фондового рынка за 3 дня, и это было успешно сделано. Она забыла пароль к компьютеру, на котором находится единственный экземпляр программы. Рабочий день Клавы составляет 8 часов. Пароль состоит из четырёх цифр от 0 до 9, а каждый вариант проверяется 10 секунд. Какое минимальное количество рабочего времени понадобится Клаве в худшем случае, чтобы закончить работу над проектом как можно быстрее?","choices":["менее 8 часов","от 8 до 18 часов","ровно 18 часов","ровно 24 часа","более 27 часов"],"points":5,"steps":["Всего четырёхзначных записей 10⁴ = 10000, включая ведущие нули. Последний вариант в списке может оказаться верным, тогда проверка займёт 100000 секунд, то есть 27 ч 46 мин 40 с.","Снова написать программу можно за 3 · 8 = 24 рабочих часа. Это короче худшего случая при проверке пароля."],"answer":3},{"title":"Кабели без узлов","question":"Петя Шнуров работает в организации, проводящей сеть для предприятий. Однажды, достав сетевые кабели из сумки, он обнаружил следующую картину. Сколько кабелей НЕ завяжутся в узел, если аккуратно потянуть за концы в разные стороны?","choices":["1","2","3","4","0"],"points":5,"steps":["Восстанови ход каждого кабеля, учитывая, где линия уходит под другую. Можно повторить его шнурком на столе.","У кабелей 1 и 4 петли расправятся. У 2 и 3 шнур проходит через петлю, которая затягивается. Без узла останутся два кабеля."],"answer":1,"figure":{"src":"assets/kit/2011/6-7-23.svg","alt":"Четыре кабеля со схемами пересечений."}},{"title":"Монета вокруг монеты","question":"На столе лежат две одинаковые круглые монеты. Одна из них закреплена, а другая совершает один оборот, катясь вокруг первой без проскальзывания и всё время соприкасаясь с закреплённой монетой. Сколько оборотов вокруг своей оси сделает катящаяся монета?","choices":["1","2","3","4","0"],"points":5,"steps":["Центр подвижной монеты идёт по окружности радиуса 2r. Это расстояние 4πr за круг.","Поворот монеты при качении можно измерить по пройденным длинам её собственной окружности 2πr. Отношение 4πr / 2πr = 2. Можно проверить по метке: на полпути она уже снова смотрит в исходную сторону."],"answer":1},{"title":"Палиндромы на счётчике","question":"Программист Серёжа написал программу по проверке сбойных секторов на диске и увидел, что проверено 25952 сектора. Ровно через 2 секунды счётчик показал ближайшее следующее число, которое читается одинаково в обоих направлениях. Сколько секторов проверяется за секунду?","choices":["25","2","55","4","110"],"points":5,"steps":["Чтобы найти следующий палиндром, увеличь первые три цифры 259 до 260. Отрази две первые цифры в конец: получится 26062.","Проверили 26062 − 25952 = 110 новых секторов за две секунды. За секунду проверяют 55."],"answer":2},{"title":"Пять надписей на доске","question":"На доске в компьютерном классе написаны утверждения. Верным утверждением является надпись с номером…","choices":["1","2","3","4","5"],"points":5,"steps":["Две разные надписи не могут быть верны одновременно: они называют разное число ошибок. Значит, верных максимум одна.","Если верных ноль, неверных было бы пять. Тогда пятая надпись стала бы верной. Следовательно, верна ровно одна, неверных четыре. Подходит надпись 4."],"answer":3,"context":"1. На доске ровно 1 неверное утверждение.\n2. На доске ровно 2 неверных утверждения.\n3. На доске ровно 3 неверных утверждения.\n4. На доске ровно 4 неверных утверждения.\n5. На доске ровно 5 неверных утверждений."},{"title":"Конец произведения от 1 до 9","question":"Какой цифрой оканчивается произведение всех чисел от 1 до 9 включительно?","choices":["0","2","8","4","9"],"points":5,"steps":["Найди в произведении числа 2 и 5. Вместе они дают 10.","Произведение содержит множитель 10, поэтому делится на 10 и оканчивается нулём."],"answer":0},{"title":"Две книги на полке","question":"Вася Чайников поставил на полку две книги: сначала «C++ для чайников», а справа от неё «C# для чайников». Толщина каждой книги без учёта обложки составляет 20 мм, толщина обложки — 2 мм. Книжный червь прогрыз норку от первой страницы «C++ для чайников» до последней страницы «C# для чайников». Какова длина норки?","choices":["40 мм","22 мм","24 мм","4 мм","44 мм"],"points":5,"steps":["Посмотри на книги с корешками к себе. Первая страница левой книги лежит у правой обложки, последняя страница правой — у левой.","Между этими страницами только две обложки. Общая толщина 2 + 2 = 4 мм, через стопки страниц червь не проходит."],"answer":3,"figure":{"src":"assets/kit/2011/6-7-28.webp","alt":"Две книги на полке корешками к зрителю."}},{"title":"Белые клетки квадрата","question":"На рисунке показан алгоритм закраски квадратов со сторонами 5 и 7. Сколько белых полей имеет аналогичный квадрат со стороной 9?","choices":[],"points":5,"steps":["В квадрате 9 на 9 всего 81 клетка. Внешний ряд белый, а внутри поле 7 на 7 закрашено через клетку.","На внутреннем поле тёмных клеток 4 + 3 + 4 + 3 + 4 + 3 + 4 = 25. Белых во всём квадрате 81 − 25 = 56."],"numericAnswer":56,"figure":{"src":"assets/kit/2011/6-7-29.svg","alt":"Два квадратных поля со сторонами 5 и 7 клеток."}},{"title":"Один литр в чайнике","question":"У Димы имеются три чайника. Объём первого 4 литра, второго — 7 литров, а третий вмещает не меньше литра, но его точный объём неизвестен. В третьем чайнике вода вскипает быстрее всего. Все три чайника сначала пусты и не имеют мерных делений. За какое наименьшее количество действий Дима может гарантированно отмерить и перелить ровно 1 литр в третий чайник? Каждое наливание или выливание считается за одно действие.","choices":[],"points":5,"steps":["Наполни четырёхлитровый чайник и перелей воду в семилитровый. В большом чайнике останется место для 3 литров.","Снова набери 4 литра в маленький и долей 3 литра в большой до края. В маленьком останется ровно литр.","Перелей этот литр в третий чайник. Получается пять шагов. Для неизвестного объёма остаток в 1 литр нужно гарантированно получить с помощью чайников 4 и 7 литров. После первого обмена водой между полным и пустым чайниками известны количества 4 и 7 литров или разность 3 литра. Чтобы получить 1 литр, нужно ещё раз наполнить один чайник и перелить воду, поэтому получить 1 литр за три действия до последнего переливания нельзя."],"numericAnswer":5,"adaptation":"Уточнено, что нужен способ, работающий для любого объёма третьего чайника, который вмещает 1 литр."}]);
edition.sources.readers = {"tasksUrl":"assets/kit/2011/6-7-reading.pdf"};
